/* ===================== BÀI 4 · Lab đầu tiên: LED có dự đoán ===================== */
/* Bài 4 · Lab đầu tiên: LED có dự đoán (AMTS-EMB-001-M01-L04, MC51-004) — sinh bởi tools/author/mcu8051/l04.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR4=[{"label":"Ví dụ: Mẫu 3CH trên tám LED","code":"        ORG     0000H\n        MOV     P1,#3CH                 ; 0011 1100B\n        SJMP    $\n        END\n","note":"Đoán trước: 3CH = 0011 1100B, LED nào sáng? Bấm Từng bước: LED P1.0, P1.1, P1.6, P1.7 sáng (các bit 0), P1.2–P1.5 tắt. Lệnh MOV P1,#3CH có mã 75 90 3C, 3 byte, 2 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Bật, tắt, đảo từng LED bằng lệnh bit","code":"        ORG     0000H                   ; sau reset P1 = FFH\n        CLR     P1.0                    ; FEH: LED P1.0 sáng\n        CLR     P1.7                    ; 7EH: thêm LED P1.7\n        CPL     P1.0                    ; 7FH: LED P1.0 tắt\n        SETB    P1.7                    ; FFH: LED P1.7 tắt\n        CPL     P1.3                    ; F7H: LED P1.3 sáng\n        SJMP    $\n        END\n","note":"Năm lệnh bit, mỗi lệnh 2 byte, 1 chu kỳ. Theo dõi chốt P1 trong phần Thanh ghi: FFH → FEH → 7EH → 7FH → FFH → F7H. Byte thứ hai của mỗi lệnh là địa chỉ bit 90H + n.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Đếm nhị phân trên LED tích cực mức thấp","code":"        ORG     0000H\n        MOV     R7,#5                   ; đếm 5 lần\n        CLR     A\nDEM:    INC     A                       ; A = 1, 2, 3, 4, 5\n        CPL     A                       ; đảo: bit 1 → chân 0 → LED sáng\n        MOV     P1,A\n        CPL     A                       ; trả A về giá trị đếm\n        DJNZ    R7,DEM\n        SJMP    $\n        END\n","note":"Vòng DEM chạy 5 lần, mỗi lần 6 chu kỳ. A giữ số đếm 1…5; P1 nhận số đã đảo bit: FEH, FDH, FCH, FBH, FAH. Đoán trước: sau lần thứ 3, LED nào sáng? (A = 03H nên LED P1.0 và P1.1.) Chọn tốc độ Từ từ để thấy LED đếm.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Chạy đèn bằng lệnh RL A","code":"        ORG     0000H\n        MOV     A,#0FEH                 ; chỉ bit 0 = 0: LED P1.0\n        MOV     R7,#8\nCHAY:   MOV     P1,A                    ; xuất mẫu ra LED\n        RL      A                       ; dịch vòng trái 1 bit\n        DJNZ    R7,CHAY\n        SJMP    $\n        END\n","note":"Một LED sáng chạy từ P1.0 tới P1.7: P1 = FEH, FDH, FBH, F7H, EFH, DFH, BFH, 7FH. Đoán trước: sau vòng lặp A bằng bao nhiêu? (FEH: 8 lần dịch vòng 8 bit trở về giá trị đầu.) Cả 8 bước chỉ 34 µs ở 12 MHz.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Quên đảo bit, bảy LED sáng","code":"        ORG     0000H\n; ý định: chỉ LED P1.0 sáng\n        MOV     P1,#01H                 ; bit 0 = 1 → chân P1.0 = 1\n        SJMP    $\n        END\n","note":"Ý định là chỉ LED P1.0 sáng, nhưng 01H = 0000 0001B: chân P1.0 = 1 (tắt), bảy chân còn lại = 0 nên bảy LED P1.1–P1.7 sáng. Sửa: MOV P1,#0FEH, hoặc CLR P1.0.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Viết 10 thay vì 10H","code":"        ORG     0000H\n; ý định: 10H = 0001 0000B, chỉ LED P1.4 tắt\n        MOV     P1,#10                  ; thiếu chữ H: 10 thập phân\n        SJMP    $\n        END\n","note":"Không có chữ H nên 10 là số thập phân = 0AH = 0000 1010B: LED P1.1 và P1.3 tắt, sáu LED còn lại sáng. Ý định là 10H = 0001 0000B (chỉ LED P1.4 tắt). Sửa: MOV P1,#10H.","dev":{"led":true},"fosc":12000000}];
const sim4=makeSim51(document.getElementById("m51-l4"),{id:"s4",presets:PR4,ram:256});
makeEx51(document.getElementById("ex-l4"),"l4",[{"t":"Mẫu đèn và đèn nguồn","d":"<p>Bo có 8 LED nối P1, sáng khi chân = 0. LED P1.7 dùng làm đèn báo nguồn: luôn sáng. LED P1.6 dự phòng: luôn tắt. Ô <code>30H<\/code> chứa mẫu cho 6 LED còn lại: bit <i>k<\/i> = 1 nghĩa là LED P1.<i>k<\/i> sáng (<i>k<\/i> = 0–5); bit 6, 7 của <code>30H<\/code> bị bỏ qua. Viết chương trình xuất ra <code>P1<\/code>, rồi ghi vào <code>31H<\/code> mẫu sáng thật của cả 8 LED (bit = 1 nghĩa là LED đó sáng) để chương trình khác đọc lại. Ô <code>30H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 05H<\/code> → LED P1.0, P1.2, P1.7 sáng: <code>P1 = 7AH<\/code>, <code>31H = 85H<\/code>.<\/p>","start":"        ORG     0000H\n; 30H: bit k = 1 → LED P1.k sáng (k = 0..5)\n; P1.6 luôn tắt, P1.7 luôn sáng (đèn nguồn)\n        MOV     A,30H\n        MOV     P1,A                    ; chưa đúng: LED sáng ngược\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":5,"0x31":238}},"expect":{"iram":{"0x30":5,"0x31":133},"ports":{"P1":122}}},{"setup":{"iram":{"0x30":0,"0x31":238}},"expect":{"iram":{"0x30":0,"0x31":128},"ports":{"P1":127}}},{"setup":{"iram":{"0x30":255,"0x31":238}},"expect":{"iram":{"0x30":255,"0x31":191},"ports":{"P1":64}}},{"setup":{"iram":{"0x30":63,"0x31":238}},"expect":{"iram":{"0x30":63,"0x31":191},"ports":{"P1":64}}},{"setup":{"iram":{"0x30":192,"0x31":238}},"expect":{"iram":{"0x30":192,"0x31":128},"ports":{"P1":127}}},{"setup":{"iram":{"0x30":42,"0x31":238}},"expect":{"iram":{"0x30":42,"0x31":170},"ports":{"P1":85}}}]},"hints":["Ba bước trên A: đảo bit (LED tích cực mức thấp), ép bit 7 về 0 (P1.7 sáng), ép bit 6 lên 1 (P1.6 tắt).","ANL A,#7FH xóa bit 7 mà giữ các bit khác; ORL A,#40H đặt bit 6. Thứ tự: CPL A trước rồi mới ANL/ORL.","31H lưu mẫu theo nghĩa 1 = sáng, còn P1 dùng 0 = sáng: từ giá trị vừa ghi ra P1, cần thêm một phép biến đổi nữa."],"why":"Mẫu trong 30H viết theo nghĩa “1 = sáng”, còn chân phải bằng 0 để LED sáng, nên phải CPL A. Bit 6, 7 phải được ép bằng mặt nạ sau khi đảo; bộ thử 3 (30H = FFH) bắt lỗi để LED P1.6 sáng theo bit rác."},{"t":"Bật đúng một LED","d":"<p>Ô <code>30H<\/code> chứa số thứ tự <i>k<\/i> của LED cần bật. Nếu <i>k<\/i> = 0–7: chỉ LED P1.<i>k<\/i> sáng (các LED khác tắt). Nếu <i>k<\/i> lớn hơn 7 (dữ liệu sai): không bật LED nào, <code>P1<\/code> giữ <code>FFH<\/code> như sau reset. Ô <code>30H<\/code> giữ nguyên. Toàn chương trình chạy không quá <b>60 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>). Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 03H<\/code> → <code>P1 = F7H<\/code> (1111 0111B, chỉ LED P1.3 sáng).<\/p>","start":"        ORG     0000H\n; 30H = k: chỉ bật LED P1.k (k = 0..7)\n; k > 7: không bật LED nào\n; Viết code ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3}},"expect":{"iram":{"0x30":3},"ports":{"P1":247}}},{"setup":{"iram":{"0x30":0}},"expect":{"iram":{"0x30":0},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":7}},"expect":{"iram":{"0x30":7},"ports":{"P1":127}}},{"setup":{"iram":{"0x30":8}},"expect":{"iram":{"0x30":8},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":255}},"expect":{"iram":{"0x30":255},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":5}},"expect":{"iram":{"0x30":5},"ports":{"P1":223}}}],"maxCyc":60},"hints":["Mẫu một LED sáng là FEH dịch vòng trái k lần (RL A): FEH, FDH, FBH, F7H…","DJNZ với bộ đếm bằng 0 sẽ lặp 256 lần (768 chu kỳ: mẫu cuối tình cờ vẫn đúng vì 256 lần quay là 32 vòng trọn, nhưng vượt giới hạn 60 chu kỳ). Cách gọn: bắt đầu từ 7FH và quay k + 1 lần (INC R7 trước vòng lặp).","Loại trường hợp không hợp lệ trước: một lệnh vừa so sánh vừa đặt CY, rồi rẽ nhánh theo CY."],"why":"Một bit 0 duy nhất dịch tới vị trí k cho đúng một LED sáng. Dữ liệu ngoài phạm vi phải cho trạng thái an toàn (mọi LED tắt); bộ thử k = 8 và k = 255 bắt chương trình quay vòng mà không kiểm phạm vi. Bộ thử k = 0 bắt vòng DJNZ bắt đầu với bộ đếm 0: mẫu tình cờ đúng (256 lần quay trả lại mẫu cũ) nhưng mất khoảng 780 chu kỳ, vượt giới hạn 60 chu kỳ."},{"t":"LED gương dưới 24 chu kỳ","d":"<p>Dải LED bị lắp ngược: LED P1.<i>k<\/i> phải hiển thị bit (7 − <i>k<\/i>) của ô <code>30H<\/code> (bit = 1 nghĩa là LED sáng). Code mẫu làm đúng nhưng chậm. Hãy viết lại để: (1) <code>P1<\/code> đúng mẫu gương; (2) ô <code>30H<\/code> giữ nguyên; (3) toàn chương trình chạy không quá <b>24 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>34 byte<\/b>. Được dùng A, B, R0–R7 và cờ CY tùy ý.<\/p><p>Ví dụ: <code>30H = 01H<\/code> → chỉ LED P1.7 sáng: <code>P1 = 7FH<\/code>.<\/p>","start":"        ORG     0000H\n; LED P1.k sáng khi bit (7 - k) của 30H = 1\n        MOV     A,30H\n        MOV     R7,#8\nDAO:    RLC     A                       ; bit cao nhất ra CY\n        XCH     A,R6\n        RRC     A                       ; CY vào bit cao của R6\n        XCH     A,R6\n        DJNZ    R7,DAO\n        MOV     A,R6                    ; A = 30H đảo thứ tự bit\n        CPL     A                       ; LED tích cực mức thấp\n        MOV     P1,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1}},"expect":{"iram":{"0x30":1},"ports":{"P1":127}}},{"setup":{"iram":{"0x30":0}},"expect":{"iram":{"0x30":0},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":255}},"expect":{"iram":{"0x30":255},"ports":{"P1":0}}},{"setup":{"iram":{"0x30":15}},"expect":{"iram":{"0x30":15},"ports":{"P1":15}}},{"setup":{"iram":{"0x30":160}},"expect":{"iram":{"0x30":160},"ports":{"P1":250}}},{"setup":{"iram":{"0x30":18}},"expect":{"iram":{"0x30":18},"ports":{"P1":183}}},{"setup":{"iram":{"0x30":60}},"expect":{"iram":{"0x30":60},"ports":{"P1":195}}}],"maxCyc":24,"maxBytes":34},"hints":["Chạy code mẫu: khoảng 55 chu kỳ. Mỗi vòng tốn 6 chu kỳ cho 1 bit, trong đó XCH hai lần và DJNZ là phần “phụ”.","Lệnh bit chép thẳng một bit vào CY: MOV C,bit (1 chu kỳ, 2 byte). Thanh ghi B có địa chỉ bit: B.0 … B.7.","Không cần vòng lặp: MOV C,bit lấy đúng một bit nguồn, lệnh xoay qua cờ nhớ đẩy nó vào A. Lấy các bit theo thứ tự nào thì sau 8 lần A là ảnh gương?"],"why":"Bỏ vòng lặp và thay hai lệnh XCH bằng lệnh bit MOV C,B.k: 2 + 8 × 2 + 1 + 1 + 2 = 22 chu kỳ, 32 byte. Đây là đổi kích thước mã lấy tốc độ: code mẫu dùng vòng lặp chỉ 16 byte nhưng 55 chu kỳ."}]);

makeQuiz("quiz4","score4",[{"q": "LED nối P1 sáng khi chân = 0. Sau lệnh MOV P1,#3CH, những LED nào sáng?", "o": ["P1.0, P1.1, P1.6, P1.7", "P1.2, P1.3, P1.4, P1.5", "P1.0, P1.1, P1.2, P1.3", "Không LED nào, vì 3CH khác 00H"], "a": 0, "e": "3CH = 0011 1100B. LED sáng ở các bit 0: bit 0, 1, 6, 7. Chọn P1.2–P1.5 là quên rằng LED tích cực mức thấp."}, {"q": "Ngay sau reset, chạy lần lượt CLR P1.0, CLR P1.7, CPL P1.0, SETB P1.7, CPL P1.3. Chốt P1 cuối cùng bằng bao nhiêu?", "o": ["08H", "F7H", "7EH", "FEH"], "a": 1, "e": "FFH → FEH → 7EH → 7FH → FFH → F7H. Mỗi lệnh bit chỉ đổi một chân và giữ nguyên các chân khác. 08H là kết quả khi viết bit đảo ngược (nghĩ 1 = sáng)."}, {"q": "Chương trình đếm đang chạy, bạn nhấn nút reset trên bo rồi thả ra. Từ lúc reset tới khi chương trình ghi P1 lần đầu, 8 LED tích cực mức thấp thế nào?", "o": ["Giữ nguyên mẫu ngay trước khi reset", "Sáng hết, vì reset xóa P1 về 00H", "Sáng mờ đều, vì CPU đang dừng", "Tắt hết, vì reset đặt chốt P1 = FFH"], "a": 3, "e": "Reset đặt chốt P0–P3 = FFH, mọi chân ở mức 1 nên LED tích cực mức thấp tắt. Reset xóa A, B, PSW về 00H nhưng cổng thì về FFH; RAM trong mới là phần giữ nguyên."}, {"q": "Trình dịch Keil A51 dịch lệnh SETB P1.7 thành mã máy nào?", "o": ["D2 90 07", "75 90 80", "D2 97", "D3 97"], "a": 2, "e": "SETB bit có mã D2H, theo sau là địa chỉ bit: P1.7 = 90H + 7 = 97H, tổng 2 byte. 75 90 80 là MOV P1,#80H (ghi cả byte); D3 là SETB C (cờ nhớ), không có toán hạng."}, {"q": "Mỗi LED trên P1 được thiết kế cho dòng 10 mA. Cả 8 LED cùng sáng thì có vấn đề gì theo datasheet AT89S52?", "o": ["Không vấn đề, mỗi chân chịu được 10 mA", "Tổng 80 mA vượt giới hạn 15 mA của cả cổng P1", "Chỉ vượt giới hạn khi thạch anh 12 MHz", "Chip tự giới hạn dòng nên LED chỉ mờ đi"], "a": 1, "e": "Ghi chú đặc tính DC giới hạn 10 mA mỗi chân nhưng chỉ 15 mA cho cả cổng P1 ở trạng thái ổn định. Đúng từng chân nhưng sai cả cổng; tần số thạch anh không liên quan."}]);

